@Injectable()
export class RoleBasedAuthGuard {
  /**
   * @param {string[]} requiredPermissions - Array of permission names required for the route.
   */
  constructor(private readonly requiredPermissions: string[]) {}

  canActivate(): boolean {
    const req = context.req;

    if (req.user && req.user.roles.includes(this.requiredPermissions[0])) {
      // Check additional required permissions if more than one exists
      for (const perm of this.requiredPermissions.slice(1)) {
        if (!req.user.permissions.includes(perm)) {
          return false;
        }
      }
      return true;
    }
    return false;
  }
}
